/**
 * Migration Script: Invoices Collection
 *
 * Reads invoices nested inside vendors (old structure)
 * Writes into standalone invoices collection (new structure)
 *
 * For each vendor:
 *   Take ONLY the LAST invoice URL → create ONE invoice document
 *
 * invoice_no & invoice_id are generated by Mongoose model:
 *   - invoice_no via Counter + pre-save
 *   - invoice_id via default generateUniqueId("INV")
 */

import { MongoClient } from "mongodb";
import mongoose from "mongoose";

// 🔺 FIX THIS PATH as per your project structure
// e.g. "../models/invoices.js" or "./models/invoices.js"
import { Invoices } from "../models2/invoices.js";

// CONNECTIONS
const MONGO_URI_SOURCE =
  process.env.MONGO_URI_SOURCE ||
  "mongodb+srv://eventorycareers:C%40reersEventory1234@eventory-prod.wrbi9gg.mongodb.net/dev?retryWrites=true&w=majority&appName=eventory-prod";

const MONGO_URI_DEST =
  process.env.MONGO_URI_DEST ||
  "mongodb+srv://eventory:eventory%40123@migrateprod.oo7xcqs.mongodb.net/prod?retryWrites=true&w=majority";

const LIMIT = process.env.LIMIT ? parseInt(process.env.LIMIT) : null;
const DRY_RUN = process.env.DRY_RUN === "true";

/**
 * Capitalize first 3 characters of ID
 * ven2025 -> VEN2025
 */
function normalizeIdPrefix(id) {
  if (!id) return null;
  if (typeof id !== "string") return id;
  if (id.length < 3) return id.toUpperCase();
  return id.substring(0, 3).toUpperCase() + id.substring(3);
}

async function migrateInvoices() {
  let sourceClient;

  try {
    console.log("🔌 Connecting to SOURCE MongoDB (old vendors)...");
    sourceClient = new MongoClient(MONGO_URI_SOURCE);
    await sourceClient.connect();
    console.log("✓ Connected to SOURCE");

    console.log("🔌 Connecting to DESTINATION MongoDB via Mongoose (Invoices)...");
    await mongoose.connect(MONGO_URI_DEST, {
      // options if needed
    });
    console.log("✓ Connected to DESTINATION\n");

    if (DRY_RUN) {
      console.log("⚠ DRY RUN MODE ENABLED — NO WRITES WILL OCCUR.\n");
    }

    const sourceDb = sourceClient.db("dev");
    const vendorsCollection = sourceDb.collection("vendors");

    console.log("📥 Fetching vendors...");
    let query = vendorsCollection.find({});
    if (LIMIT) query = query.limit(LIMIT);

    const vendors = await query.toArray();
    console.log(`📊 Loaded ${vendors.length} vendors.\n`);

    let success = 0;
    let failed = 0;
    const errors = [];

    for (let i = 0; i < vendors.length; i++) {
      const vendor = vendors[i];
      console.log(
        `[${i + 1}/${vendors.length}] Vendor: ${vendor.id} (${vendor.name || "N/A"})`
      );

      const vendorId = normalizeIdPrefix(vendor.id);

      // Must have invoices
      if (!vendor.invoices || vendor.invoices.length === 0) {
        console.log("  ⚠ No invoices found — skipping\n");
        continue;
      }

      // Take ONLY the LAST invoice URL
      const invoiceUrl = vendor.invoices[vendor.invoices.length - 1];

      if (!invoiceUrl || typeof invoiceUrl !== "string") {
        console.log("  ⚠ Invalid invoice URL — skipping\n");
        continue;
      }

      // Must have at least one serviceId
      if (!vendor.serviceIds || vendor.serviceIds.length === 0) {
        failed++;
        errors.push({
          vendor: vendor.id,
          error: "No serviceIds found — cannot derive service_id",
        });
        console.log("  ✗ ERROR: No serviceIds found\n");
        continue;
      }

      const mainService = vendor.serviceIds[0];
      const serviceId = normalizeIdPrefix(mainService.serId);

      try {
        // Check if already migrated (by URL)
        const existing = await Invoices.findOne({ invoice_url: invoiceUrl });
        if (existing) {
          console.log("  ⚠ Invoice already exists — skipping\n");
          continue;
        }

        const invoiceBase = {
          invoice_url: invoiceUrl,
          type: "registration",
          vendor_id: vendorId,
          service_id: serviceId,
          customer_id: null, // required to be null for registration
          event_id: null, // required to be null for registration
          // invoice_no, invoice_id, invoice_created_at handled by schema + middleware
        };

        if (!invoiceBase.vendor_id || !invoiceBase.service_id) {
          throw new Error("Missing vendor_id or service_id");
        }

        if (DRY_RUN) {
          console.log("  DRY RUN — would create invoice document:", invoiceBase);
        } else {
          const invoiceDoc = new Invoices(invoiceBase);
          await invoiceDoc.save(); // 🔥 This triggers:
          // - default invoice_id: generateUniqueId("INV")
          // - auto-increment invoice_no via Counter
          // - invoice_created_at IST default
          console.log(
            `  ✓ Migrated invoice: ${invoiceUrl} → invoice_no=${invoiceDoc.invoice_no}, invoice_id=${invoiceDoc.invoice_id}`
          );
        }

        success++;
        console.log("");
      } catch (err) {
        failed++;
        errors.push({
          vendor: vendor.id,
          invoice_url: invoiceUrl,
          error: err.message,
        });
        console.log(`  ✗ ERROR inserting invoice: ${err.message}\n`);
      }
    }

    // SUMMARY
    console.log("\n==============================");
    console.log("INVOICES MIGRATION SUMMARY");
    console.log("==============================");
    console.log("Total vendors processed:", vendors.length);
    console.log("Successful invoices:", success);
    console.log("Failed invoices:", failed);

    if (errors.length > 0) {
      console.log("\n❌ Errors:");
      errors.forEach((e) => {
        console.log(
          `  Vendor ${e.vendor} | URL: ${e.invoice_url || "N/A"} → ${e.error}`
        );
      });
    }

    console.log("\n✓ Migration complete.");
  } catch (err) {
    console.error("❌ Migration failed:", err);
    process.exit(1);
  } finally {
    if (sourceClient) {
      await sourceClient.close();
      console.log("🔌 Disconnected from SOURCE MongoDB");
    }
    await mongoose.disconnect();
    console.log("🔌 Disconnected from DESTINATION MongoDB");
  }
}

migrateInvoices();
